public static String underlineToCamel(String string) {
    if (string == null || string.isEmpty()) {
        return "";
    }

    // Convert first character to lowercase if uppercase
    if (Character.isUpperCase(string.charAt(0))) {
        string = Character.toLowerCase(string.charAt(0)) + string.substring(1);
    }

    int strLen = string.length();
    StringBuilder sb = new StringBuilder(strLen);

    for (int i = 0; i < strLen; i++) {
        char c = string.charAt(i);
        if (c == '_') {
            // Check if there's a next character and it's not an underscore
            if (i + 1 < strLen && string.charAt(i + 1) != '_') {
                i++; // Skip underscore
                sb.append(Character.toUpperCase(string.charAt(i)));
            }
            // Otherwise just skip the underscore (trailing or followed by another underscore)
        } else {
            sb.append(c);
        }
    }

    return sb.toString();
}

