public void writeInline(int ordinal, Map<FeatureId, Feature.State> stateMap) throws IOException {
    long position = view.getInlineOffset(ordinal);
    out.seek(position);

    for (Feature feature : view.inlineFeatures) {
        Feature.State state = stateMap.get(feature.id());
        if (state != null) {
            feature.writeInline(out, state);
        } else {
            out.seek(out.position() + feature.inlineSize());
        }
    }
}

