        summary.append("        %s: constraint (%s) has %s matches:\n"
                .formatted(score().toShortString(), constraintRef().constraintName(), sortedMatches.size()));

        for (int i = 0; i < displayCount; i++) {
            var match = sortedMatches.get(i);
            summary.append("            %s: justified with (%s)\n"
                    .formatted(match.score().toShortString(), match.justification()));
        }

        if (hasMore) {
            summary.append("            ... and %s more matches\n".formatted(sortedMatches.size() - maxDisplayMatches));
